<?php $pageTitle='Purchase Inquiry'; require_once __DIR__ . '/../includes/header.php'; $carId=isset($_GET['car_id'])?(int)$_GET['car_id']:(int)($_POST['car_id']??0); $car=find_car($carId); if(!$car){ set_flash('danger','Please select a valid car.'); redirect('/car-rent-sale-system/pages/cars-sale.php'); } if($_SERVER['REQUEST_METHOD']==='POST'){ $fullName=trim($_POST['full_name']); $email=trim($_POST['email']); $phone=trim($_POST['phone']); $message=trim($_POST['message']); if($fullName&&$email&&$phone){ $stmt=db()->prepare('INSERT INTO sales_inquiries (car_id, customer_name, email, phone, message, inquiry_status) VALUES (?, ?, ?, ?, ?, ?)'); $stmt->execute([$car['id'],$fullName,$email,$phone,$message,'new']); set_flash('success','Inquiry sent successfully.'); redirect('/car-rent-sale-system/pages/cars-sale.php'); } } ?><div class="container py-5"><div class="row justify-content-center"><div class="col-lg-8"><div class="form-box"><h2 class="section-title">Purchase Inquiry for <?= e($car['title']); ?></h2><form method="post"><input type="hidden" name="car_id" value="<?= (int)$car['id']; ?>"><div class="row g-3"><div class="col-md-6"><label class="form-label">Full Name</label><input class="form-control" name="full_name" required></div><div class="col-md-6"><label class="form-label">Email</label><input type="email" class="form-control" name="email" required></div><div class="col-md-6"><label class="form-label">Phone</label><input class="form-control" name="phone" required></div><div class="col-12"><label class="form-label">Message</label><textarea class="form-control" name="message" rows="4"></textarea></div><div class="col-12"><button class="btn btn-warning">Send Inquiry</button></div></div></form></div></div></div></div><?php require_once __DIR__ . '/../includes/footer.php'; ?>
